(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zy-sj-prepa-ssrpf-j5-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zy-sj-prepa-ssrpf-j5-sfm\",\n \"titre\": \"Préparation D.E (J) · J5 SSR/PF SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 60,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_SR-PF_SFM_Corrige_explique.pdf\",\n   \"sha256\": \"fac82cb699a7c78e2700572925e9d852515a7e388c0fdedc894bdd36c809f297\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J SSR / PF · Prépa D.E J5 (SFM)\",\n     \"slug\": \"prepa-ssrpf-j5-sfm\",\n     \"pages\": \"\",\n     \"count\": 60,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"SSR / PF\",\n     \"source\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU au cuivre TCU 380 A utilisé en Côte d'Ivoire a une durée d'action allant de 5 à 12 ans\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le DIU au cuivre TCU 380 A a une durée d'action pouvant aller jusqu'à 12 ans (TCU 380 A « 12 ans » dans le tableau des types de DIU). La correction nationale de la Prépa DE (les J) retient « Vrai ». Remarque : Le cours donne seulement « 12 ans » ; la borne de 5 ans de l'énoncé n'y figure pas.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 14 DIU, tableau « Types de DIU »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant une aménorrhée sous DIU il faut immédiatement penser à une grossesse extra-utérine\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le DIU ne protège pas totalement : en cas de grossesse avec un DIU en place, il faut d'abord s'assurer qu'il ne s'agit pas d'une grossesse ectopique (GEU). Une aménorrhée sous DIU impose donc d'éliminer en priorité une GEU.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 15 DIUPP, « Grossesse avec un DIU en place » ; complications : « Risque de GEU »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une cliente sous DIU peut avoir comme effet secondaire l'augmentation de son flux menstruel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'augmentation du flux menstruel fait partie des effets secondaires du DIU (avec les saignements prolongés, les crampes, la métrorragie). Elle est surtout marquée pendant les premiers cycles avec le DIU au cuivre.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 14 DIU, tableau « Effets secondaires et complications »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ancrage, les rapports sexuels douloureux et les infections pelviennes sont des complications qui peuvent survenir chez une cliente sous un dispositif intra-utérin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours classe parmi les complications du DIU : la perforation pendant la pose, la migration, l'ancrage, le risque de GEU, les infections pelviennes graves et le rapport sexuel douloureux. Les trois éléments cités sont bien des complications.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 14 DIU, tableau « Effets secondaires et complications »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une cliente qui n'a pas assez de lait ne peut pas faire la MAMA\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les 3 conditions de la MAMA sont : allaitement exclusif (6 à 8 tétées/24 h), femme aménorrhéique, post-partum < 6 mois. L'abondance du lait n'en fait pas partie ; le cours range d'ailleurs « la montée laiteuse importante est la principale condition » parmi les affirmations à corriger. Une mère qui allaite exclusivement peut donc utiliser la MAMA même si elle pense avoir « peu de lait ».\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 10 MAMA, « Conditions d'efficacité » + Annexe (questionnaire)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le fort taux de la prolactine dépend du nombre, de la qualité, de la fréquence et de la durée des tétées\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours indique que le taux de prolactine est fonction du nombre, de la qualité, de la fréquence des tétées et de la durée de l'allaitement ; plus il est élevé, plus l'effet contraceptif de la MAMA est fort.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 10 MAMA, « Mécanisme d'action »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Tous les COC contiennent 21 pilules actives\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Il existe des plaquettes de 21 pilules et des plaquettes de 28 pilules (la plaquette de 28 s'enchaîne sans arrêt). Les COC ne se présentent donc pas tous de la même façon, d'où « Faux ». Remarque : Le cours parle de plaquettes de 21 et de 28 pilules sans préciser le nombre de pilules actives dans la plaquette de 28.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 12 CHC, « Instructions pour l'utilisation des COC »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les adolescents et jeunes venant à la consultation ont le droit d'être reçus dans des conditions confortables\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le counseling des adolescents doit créer un climat de confiance, insister sur le caractère privé et confidentiel de l'entretien et éviter tout ce qui pourrait les décourager de consulter : ils ont droit à un accueil dans de bonnes conditions. (explication partiellement hors cours du projet)\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 17 Groupes particuliers, « Counseling chez les adolescents »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les COC sont classés en 4 groupes en fonction du dosage\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Dans le cours, les COC sont classés en 3 groupes selon le dosage en éthinylestradiol (minidosés 15-40 µg, normodosés 50 µg, fortement dosés > 50 µg) et en 4 générations selon le type de progestatif.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 12 CHC, « Caractéristiques des COC »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les COC peuvent être administrés à une allaitante de 6 semaines si elle le désire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Allaitement entre 6 semaines et 6 mois : catégorie 3 de l'OMS pour les COC (les risques l'emportent sur les avantages). On ne donne donc pas les COC à une allaitante de 6 semaines simplement parce qu'elle le désire ; on préfère une méthode progestative.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 12 CHC, « Critères médicaux d'éligibilité » (Post-partum)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contraceptifs oraux combinés diminuent l'effet hypoglycémique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le tableau des interférences médicamenteuses, les hypoglycémiants (Diabinèse, Tolbutamide…) associés aux COC : « Diminution possible de l'effet hypoglycémique » ; il faut surveiller la glycémie.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 12 CHC, « Interférence médicamenteuse »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contraception d'urgence consiste à administrer une méthode contraceptive après un rapport sexuel non protégé, dans une période où le couple ne souhaite absolument pas de grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Définition du cours : la contraception d'urgence est l'administration d'une méthode contraceptive suite à un rapport sexuel non protégé, à une période du cycle où le risque de grossesse non désirée est élevé (contraception post-coïtale).\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 17, « Contraception d'urgence »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU au cuivre peut être utilisé en contraception d'urgence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le DIU au cuivre peut être utilisé comme contraception d'urgence s'il est posé dans les 5 jours suivant le rapport ; le DIU hormonal, lui, ne l'est pas.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 14 DIU (tableau) et chap. 17 « Contraception d'urgence »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La Contraception Chirurgicale Volontaire est obligatoire chez les femmes ayant des antécédents médico-chirurgicaux ou obstétricaux contre-indiquant la grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les femmes ayant des antécédents contre-indiquant la grossesse font partie des bénéficiaires de la CCV, mais celle-ci reste volontaire : elle n'est pratiquée qu'après consentement écrit et éclairé, que la cliente peut retirer à tout moment. Elle n'est jamais obligatoire.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 16 CCV, « Bénéficiaires » et « Principe du consentement écrit et volontaire »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La planification familiale est bénéfique pour la population car, sur le plan démographique, elle assure un bon équilibre entre population et ressources et contribue ainsi à résoudre les problèmes de développement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avantage démographique de la PF : établissement d'un bon équilibre entre population et ressources. Le cours précise que la PF seule ne résout pas les problèmes de développement mais y contribue.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 2 Concept de la PF, « Avantages de la PF »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Si le centre a plus que le minimum, il est surstocké et risque d'avoir des quantités qui périmeront avant leur utilisation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai » : un niveau de stock trop élevé expose à la péremption des produits avant utilisation. Le cours reprend cette phrase parmi les affirmations Vrai/Faux du prétest de gestion logistique (« Tout niveau de stock supérieur au minimum est une situation de sur stockage »), sans donner la réponse. (explication partiellement hors cours du projet) Remarque : Dans le système max-min classique, on parle de surstockage au-dessus du stock MAXIMUM (entre le minimum et le maximum, le stock est normal).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, Annexe 2 « Questionnaire prétest gestion logistique », item 17\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le stock d'alerte = stock minimum + stock de sécurité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Option 1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Option 2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Option 2\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) coche « Option 2 », ce qui correspond à « Faux ». En gestion logistique, le stock d'alerte (seuil de commande) se calcule à partir du stock de sécurité et de la consommation pendant le délai de livraison ; ce n'est pas l'addition « stock minimum + stock de sécurité » (le stock de sécurité fait déjà partie du minimum). (explication hors cours du projet) Remarque : Dans le sujet, les deux réponses sont libellées « Option 1 » et « Option 2 » au lieu de V et F ; « Option 2 » est lue ici comme « Faux ».\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le soutien social et environnemental est une des composantes de la gestion de l'hygiène menstruelle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La gestion de l'hygiène menstruelle ne se limite pas aux protections : elle comprend l'accès à l'information, à l'eau et à l'assainissement, aux produits, à l'élimination des déchets, et le soutien social et environnemental (lutte contre les tabous, la stigmatisation). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La survenue de saignement tous les 21 à 35 jours s'appelle le cycle menstruel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cycle menstruel est la période qui va du 1er jour des règles au 1er jour des règles suivantes (ou au dernier jour qui les précède). Le saignement lui-même est la menstruation (les règles), pas le cycle.\\n\\nSource : Cours Gynéco-Obstétrique 1re année INFAS, « Cycle menstruel normal » ; Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), Annexe\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'utilisation de tampons à haut pouvoir absorbant en cas de perte légère de sang pendant les menstrues n'est pas un risque pour la santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Utiliser des tampons très absorbants pour un faible flux augmente le temps de port et le risque d'infection, notamment du syndrome du choc toxique. On choisit la capacité d'absorption la plus faible adaptée au flux et on change régulièrement : ce n'est donc pas sans risque. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sexe est immuable\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». (explication hors cours du projet) Remarque : La plupart des cours « Approche genre » définissent le sexe comme biologique, universel et immuable (par opposition au genre, social et variable). Le cours Genre n'est pas dans le projet : vérifier la position de l'enseignant.\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le genre permet d'identifier les différences entre les femmes et les hommes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le genre permet d'analyser les différences entre femmes et hommes construites par la société (rôles, comportements, accès aux ressources, pouvoir de décision), au-delà des seules différences biologiques. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'utilisatrice de la méthode de Billings doit savoir qu'après l'ovulation la couleur de sa glaire cervicale est mélangée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». Le tableau de la glaire décrit, après l'ovulation : quantité diminuée, consistance fine, couleur « mélangée », élasticité 4 à 6 cm.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 8 MAO, tableau « Changements de la glaire cervicale »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le genre désigne les rôles, comportements et responsabilités attribués socialement aux hommes et aux femmes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est la définition du genre : ensemble des rôles, comportements, activités et responsabilités que la société attribue aux hommes et aux femmes. Contrairement au sexe, il est appris et varie selon les cultures et les époques. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pouvoir décisionnel est un élément des six notions-pivots des fonctions sociales du genre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pouvoir de décision (qui décide dans le ménage, la communauté) fait partie des notions clés utilisées pour analyser les fonctions sociales du genre, avec les rôles, l'accès et le contrôle des ressources, les besoins, etc. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 — Mlle CHIAWA est une adolescente de 16 ans élève, souhaite finir ses études avant de faire des enfants. Elle se rend dans un centre de santé pour rencontrer la sage-femme.\",\n       \"text\": \"Que fera la sage-femme ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une Consultation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une Causerie éducative\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un Counseling\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une Communication\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un Counseling\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Mlle CHIAWA vient seule avec un besoin personnel (éviter une grossesse pour finir ses études) : c'est un counseling, entretien-conseil en tête-à-tête dans un endroit calme, où le prestataire l'aide à trouver et choisir elle-même une solution (méthode contraceptive). La causerie éducative s'adresse à un groupe.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 6 Counseling (définition) et chap. 5 Causerie éducative\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 — Mlle CHIAWA est une adolescente de 16 ans élève, souhaite finir ses études avant de faire des enfants. Elle se rend dans un centre de santé pour rencontrer la sage-femme.\",\n       \"text\": \"Choisir un de ses Principes de base nécessaires au client\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La liberté de s'exprimer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La maîtrise du sujet\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tirer les leçons du passé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'éducation par l'exemple\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La liberté de s'exprimer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les principes de base du counseling « au niveau du client » sont : caractère privé et confidentiel, liberté de choisir la méthode, liberté de s'exprimer, consentement éclairé, droits du client, renforcement de ses capacités. La maîtrise du sujet, tirer les leçons du passé et l'éducation par l'exemple sont des principes « au niveau du prestataire ».\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 6, « Principes de base nécessaires au counseling »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"LA C.C.V. se définit comme une intervention (1) …qui (2) …et irréversible à (3) … sans toutefois (4) … la sexualité et (5) … la fonction hormonale. Chez la femme, la CCV s'appelle ligature des trompes, chez l'homme c'est la vasectomie. a-Perturber b-met fin de façon définitive c-Troubler d-Chirurgicale e-Toute possibilité de reproduction sexuée. Comme vous le constatez cette définition est incomplète, reconstituez-la en choisissant la bonne association\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1-d), (2-b), (3-e), (4-c), (5-a)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(1-e), (2-d), (3-c), (4-a), (5-b)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1-a), (2-b), (3-c), (4-e), (5-d)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(1-b), (2-c), (3-a), (4-c), (5-a)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. (1-d), (2-b), (3-e), (4-c), (5-a)\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Définition du cours : « La CCV est une intervention chirurgicale (1-d) qui met fin de façon définitive (2-b) et irréversible à toute possibilité de reproduction sexuée (3-e) sans toutefois troubler (4-c) la sexualité et perturber (5-a) la fonction hormonale ».\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 16 CCV, « Définition »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La MAMA est efficace si les conditions suivantes sont réunies (Choisir 3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Abondance de lait maternel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Allaitement exclusif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Bonne succion du bébé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Femme aménorrhéiques\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Post partum inférieur à 6 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Allaitement exclusif ; D. Femme aménorrhéiques ; E. Post partum inférieur à 6 mois\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les 3 conditions d'efficacité de la MAMA (98 %) : allaitement exclusif, femme aménorrhéique, post-partum inférieur à 6 mois (bébé < 6 mois). L'abondance du lait et la bonne succion ne font pas partie des 3 conditions.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 10 MAMA, « Conditions d'efficacité »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Sont énumérés ci-dessous les avantages pour l'enfant de la MAMA sauf un ; lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Alimentation saine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bon développement psychomoteur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Permet à la mère de faire des économies\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Immunise de façon passive\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Permet à la mère de faire des économies\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avantages pour l'enfant : alimentation la plus saine, protection contre la diarrhée, lien mère-enfant, immunisation passive, bon développement psychomoteur. Le fait de ne rien coûter est un avantage pour la mère, pas pour l'enfant.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 10 MAMA, tableau « Avantages et inconvénients »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le moment favorable pour administrer les COC aux clientes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Qui ont un bon état de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"À tout moment si elles le désirent\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1 à 7 jours du cycle menstruel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 à 5 jours du cycle menstruel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 1 à 7 jours du cycle menstruel\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pour les CHC, les 7 premiers jours du cycle représentent le moment le plus indiqué pour commencer (après le 7e jour : méthode d'appoint pendant 2 jours). La fenêtre 1 à 5 jours concerne les COP.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 12 CHC, « Moment d'administration » ; chap. 13 CHP\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des avantages sanitaires de la Planification Familiale est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Diminution de la délinquance juvénile.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Amélioration de la qualité de la vie.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réduction de la mortalité et de la morbidité maternelle, périnatale et infantile.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bonne hygiène de l'environnement.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Réduction de la mortalité et de la morbidité maternelle, périnatale et infantile.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avantages sanitaires de la PF : réduction de la mortalité et de la morbidité maternelle, périnatale et infantile, des complications de la grossesse et de l'accouchement, prévention des grossesses à risque. La qualité de vie et la baisse de la délinquance sont des avantages socio-économiques ; l'hygiène de l'environnement est un avantage environnemental.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 2, tableau « Avantages de la PF »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des modes d'action des COP est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Tue les spermatozoïdes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bloque le passage des spermatozoïdes dans les trompes de Fallope\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Diminue le transport des spermatozoïdes dans les trompes de Fallope\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Diminue le transport des spermatozoïdes dans les trompes de Fallope\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Mode d'action des CHP (COP, CIP, implants) : épaississement de la glaire, modification de l'endomètre, diminution du transport des spermatozoïdes dans les trompes, blocage partiel de l'ovulation. Ils ne tuent pas les spermatozoïdes (c'est le rôle des spermicides).\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 13 CHP, « Mode d'action »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La plaquette de MICROLUT contient\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"45 comprimés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"35 comprimés\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 comprimés\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"28 comprimés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 35 comprimés\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Tableau comparatif des COP : Ovrette = 28 comprimés, Microlut (lévonorgestrel) = 35 comprimés.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 13 CHP, « Tableau comparatif des contraceptifs oraux progestatifs »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quelle classe de l'OMS se trouve une cliente qui a un cancer de l'endomètre pour les COC\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Classe 4\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Classe 3\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Classe 2\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Classe 1\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Classe 1\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Critères médicaux d'éligibilité des CHC : « cancer de l'endomètre ou de l'ovaire » = catégorie 1 pour les COC (aucune restriction). Les COC protègent même contre le cancer de l'endomètre.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 12 CHC, « Critères médicaux d'éligibilité » et « Avantages »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de Vasectomie il faut revoir le client : (choisir 3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un mois après l'intervention pour l'examen de l'éjaculat\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une semaine après l'intervention pour vérifier son consentement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"En cas de fièvre, de saignement au niveau des cicatrices et de douleurs ou inflammation au niveau du scrotum\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un mois après l'intervention pour vérifier l'érection\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Un mois après l'intervention pour l'examen de l'éjaculat ; C. En cas de fièvre, de saignement au niveau des cicatrices et de douleurs ou inflammation au niveau du scrotum\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Calendrier de suivi de la vasectomie : revoir le client un mois après l'intervention pour l'examen de l'éjaculat, et consulter en cas de fièvre, de saignement des cicatrices, de douleur ou d'inflammation du scrotum. Le consentement se vérifie avant l'intervention ; la vasectomie ne touche pas l'érection. Remarque : La question demande 3 réponses, mais seules 2 options sont cochées dans la correction nationale.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 16 CCV, « Calendrier de suivi »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant les méthodes contraceptives spécifiques pour les adolescents dans l'ordre de préférence il faut recommander\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Abstinence - Préservatifs masculin et féminin - Contraception d'urgence - Contraceptifs oraux combinés (COC)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Abstinence - Préservatifs masculin et féminin - Contraceptifs oraux combinés (COC) - Contraception d'urgence\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Préservatifs masculin et féminin - Les implants - Les méthodes d'auto-observations - Abstinence\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Abstinence - Les injectables - Préservatifs masculin et féminin - Contraceptifs oraux progestatifs (COP)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Abstinence - Préservatifs masculin et féminin - Contraceptifs oraux combinés (COC) - Contraception d'urgence\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ordre de préférence chez l'adolescent : abstinence (+++), préservatifs masculin et féminin (+++), COC (++), COP, injectables, implants (++), puis contraception d'urgence (+), DIU et méthodes d'auto-observation (+).\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 17, « Méthodes contraceptives spécifiques pour les adolescents »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les caractéristiques de la contraception en post-partum il est important de savoir que chez la femme non allaitante il faut tenir compte de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Retour des menstruations dans les 4 semaines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Première ovulation dans une moyenne de 45 jours après l'accouchement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2 femmes sur 3 vont ovuler avant de revoir les règles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Risque de survenue d'une grossesse : le plus tôt est vingt et un (21) jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Première ovulation dans une moyenne de 45 jours après l'accouchement ; D. Risque de survenue d'une grossesse : le plus tôt est vingt et un (21) jours\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Femme non allaitante : retour des règles dans les 6 semaines (et non 4), première ovulation en moyenne 45 jours après l'accouchement, risque de grossesse à partir du 21e jour.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 17, « Caractéristiques de la contraception dans le PP »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU au cuivre (TCU 380 A) utilisé en CI agit en\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réduisant le nombre des spermatozoïdes dans le sperme au niveau du col\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Altérant les spermatozoïdes les empêchant de parvenir jusqu'aux trompes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inactivant et diminuant le nombre de spermatozoïde atteignant les trompes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Atrophiant l'endomètre rendant la nidation impossible\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Modifiant l'endomètre et provoquant un environnement défavorable à la nidation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Altérant les spermatozoïdes les empêchant de parvenir jusqu'aux trompes ; C. Inactivant et diminuant le nombre de spermatozoïde atteignant les trompes ; E. Modifiant l'endomètre et provoquant un environnement défavorable à la nidation\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Mode d'action du DIU au cuivre : il altère les spermatozoïdes, inactive et diminue le nombre de spermatozoïdes qui atteignent les trompes, et modifie l'endomètre (milieu défavorable à la nidation). L'atrophie de l'endomètre relève plutôt du DIU hormonal.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 14 DIU, tableau « Types de DIU » (mode d'action)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les éléments ci-dessous sont des complications qui surviennent après la pose d'un dispositif intra-utérin : (Choisir les trois bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Migration du DIU\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Augmentation du flux menstruel\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Perforation pendant la pose (arrêter la manœuvre)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rapport sexuel douloureux\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Métrorragie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Migration du DIU ; B. Augmentation du flux menstruel ; C. Perforation pendant la pose (arrêter la manœuvre) ; D. Rapport sexuel douloureux\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Complications listées dans le cours : perforation pendant la pose (arrêter la manœuvre), migration du DIU, ancrage, risque de GEU, infections pelviennes graves, rapport sexuel douloureux.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 14 DIU, tableau « Effets secondaires et complications »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le post-abortum, le DIU peut être inséré : (Choisir les deux bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Immédiatement après l'avortement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dans les quatorze (14) premiers jours qui suivent l'avortement après avoir évalué et écarté un risque infectieux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Au-delà de cette période, si on a l'accord de la cliente\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"A n'importe quel moment après un bon counseling\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Immédiatement après l'avortement ; B. Dans les quatorze (14) premiers jours qui suivent l'avortement après avoir évalué et écarté un risque infectieux\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"En post-abortum, le DIU est proposé en l'absence absolue d'infection de la filière génitale ; il peut être posé dès la vacuité utérine, donc immédiatement après l'avortement, ou dans les jours qui suivent après avoir écarté un risque infectieux. On ne le pose pas « à n'importe quel moment ». (explication partiellement hors cours du projet) Remarque : Le délai précis de 14 jours ne figure pas dans les cours du projet.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 17 « Planification du post-abortum » ; SONU L3, Soins après avortement (« DIU dès vacuité utérine »)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 — Vous recevez Mme BOUM pour des douleurs, l'interrogatoire indique qu'elle porte un DIU depuis un an ; après un examen minutieux vous retenez qu'il s'agit d'une infection de l'endomètre.\",\n       \"text\": \"Quel traitement préconisez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des antidouleurs\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des antibiotiques à spectre large\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des antispasmodiques et du repos\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des antibiotiques et aspirine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Des antibiotiques et aspirine\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Devant une endométrite chez une porteuse de DIU, on débute immédiatement une antibiothérapie adaptée, sans retirer d'emblée le DIU. La correction nationale de la Prépa DE (les J) retient l'association antibiotiques + aspirine (anti-inflammatoire et antalgique). (explication partiellement hors cours du projet) Remarque : Le cours parle d'antibiothérapie ; l'aspirine n'y est pas mentionnée.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 15 DIUPP, « Infection »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 — Vous recevez Mme BOUM pour des douleurs, l'interrogatoire indique qu'elle porte un DIU depuis un an ; après un examen minutieux vous retenez qu'il s'agit d'une infection de l'endomètre.\",\n       \"text\": \"48 heures après le bon traitement, il y'a une amélioration, quelle décision devez-vous prendre ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer la cliente et laissez le DIU en place\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Continuer son traitement pendant une semaine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Continuer le traitement pendant 10 jours et laisser le DIU en place\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Continuer le traitement et le proposer une autre méthode pour plus de sécurité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Continuer le traitement pendant 10 jours et laisser le DIU en place\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours indique de retirer le DIU seulement en cas de septicémie ou si les symptômes ne s'améliorent pas en 72 heures. En cas d'amélioration, on poursuit le traitement complet et on laisse le DIU en place.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 15 DIUPP, « Infection »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 — Vous recevez Mme BOUM pour des douleurs, l'interrogatoire indique qu'elle porte un DIU depuis un an ; après un examen minutieux vous retenez qu'il s'agit d'une infection de l'endomètre.\",\n       \"text\": \"Qu'auriez-vous fait si le traitement avait échoué ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Retirer le DIU et référer Mme Brou\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Augmenter la dose du traitement et observer la cliente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Changer le traitement et lui donner un RDV dans 8 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Référer tout simplement Mme Brou\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Référer tout simplement Mme Brou\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"En cas d'échec du traitement, la cliente doit être référée vers un niveau de prise en charge supérieur. (explication partiellement hors cours du projet)\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 15 DIUPP, « Infection » et « Principes généraux de prise en charge »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'orientation sexuelle désigne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'attirance physique, romantique ou émotionnelle qu'une personne éprouve envers une autre personne\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une personne qui ressent une attirance physique et émotionnelle pour autrui, peu importe son identité de genre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une personne qui ne ressent pas d'attirance sexuelle pour personne.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une personne qui ressent une attirance physique et émotionnelle pour autrui, peu importe son identité de genre\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient la formulation B (attirance physique et émotionnelle pour autrui, quelle que soit son identité de genre). (explication hors cours du projet) Remarque : Les options A et B décrivent toutes deux l'orientation sexuelle ; la définition précise attendue dépend du cours Genre (absent du projet).\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les méthodes contraceptives hormonales agissent sur : (choisir 3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les spermatozoïdes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La glaire cervicale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les trompes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'endomètre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'ovulation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La glaire cervicale ; D. L'endomètre ; E. L'ovulation\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Tableau d'interférence avec les conditions de la grossesse : les méthodes hormonales agissent sur l'ovulation, la glaire cervicale et l'endomètre. Les spermicides et méthodes mécaniques agissent sur les spermatozoïdes ; la chirurgie sur les trompes.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 3, tableau « Interférence avec les conditions de grossesse »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le genre est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Déterminé par les différences biologiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un concept social\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déterminé par les différences de sexe\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Concept démographique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Un concept social\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le genre est un concept social : il désigne ce que la société attend des hommes et des femmes. Ce qui est déterminé par les différences biologiques ou de sexe relève du sexe. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En planification familiale, l'on peut être confronté à des obstacles d'ordre institutionnel tels que\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le coût des services de PF\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Insuffisance de personnel qualifié\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Manque ou insuffisances de motivation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le manque ou insuffisances de moyens financiers.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Insuffisance de personnel qualifié\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Obstacles institutionnels : absence ou insuffisance de centres de PF, insuffisance de personnel qualifié. Le coût des services et le manque de moyens financiers sont des obstacles économiques.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 2, tableau « Obstacles à la PF »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les objectifs principaux des soins de suivi des clientes du DIU est de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rechercher une Malaise intense dans la partie inférieure de l'abdomen\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Renforcer les messages clés concernant le retrait et la durée d'action\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Retirer le DIU quand elle le désire ou attendre 12 ANS pour le retrait\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Surveiller le Mois et l'année auxquels le DIU devra être retiré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Renforcer les messages clés concernant le retrait et la durée d'action\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Objectifs clés des soins de suivi : évaluer la satisfaction, identifier et gérer les problèmes, répondre aux questions et renforcer les messages clés concernant le retrait et la durée d'action.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 15 DIUPP, « Objectifs principaux des soins de suivi »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen de l'éjaculât pour la vasectomie se fait\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Deux mois après l'intervention\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un mois après l'intervention\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trois mois après l'éjaculat.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"20 éjaculats après intervention\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Un mois après l'intervention\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Revoir le client un mois après l'intervention pour l'examen de l'éjaculat. Pendant 3 mois (ou 20 éjaculations), une méthode complémentaire reste nécessaire.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 16 CCV, « Calendrier de suivi » et « Instructions »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la bonne séquence des étapes dans la chaîne logistique pharmaceutique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Commande, Réception, Stockage, Distribution\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Réception, Stockage, Commande, Distribution\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Stockage, Commande, Réception, Distribution\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Commande, Distribution, Réception, Stockage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Commande, Réception, Stockage, Distribution\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les produits sont d'abord commandés, puis réceptionnés, stockés et enfin distribués aux points de prestation et aux clients. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est l'objectif principal de l'estimation des besoins en produits de santé ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réduire le coût d'achat des produits\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Éviter les ruptures de stock et les surstocks\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Accroître la productivité du personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Augmenter les ventes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Éviter les ruptures de stock et les surstocks\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'estimation des besoins permet de commander les bonnes quantités au bon moment, donc d'éviter à la fois les ruptures de stock et les surstocks (risque de péremption). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'implication des hommes dans la gestion de l'hygiène menstruelle permet : (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De réduire les tabous\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De réduire les investissements dans les infrastructures et les produits\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D'augmenter les investissements dans les infrastructures et les produits\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Améliorer des infrastructures accessibles\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"D'impliquer les personnes handicapées dans la prise des décisions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. De réduire les tabous ; C. D'augmenter les investissements dans les infrastructures et les produits\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Impliquer les hommes dans la GHM aide à briser les tabous autour des règles et favorise les décisions d'investissement (toilettes, eau, produits) dans les ménages et les communautés, où ils sont souvent décideurs. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour une gestion de l'hygiène menstruelle efficace, notre démarche repose sur quatre piliers. Choisissez la bonne combinaison : 1. Inclusion ; 2. Durabilité ; 3. Transparence ; 4. Équité — a. Promouvoir des solutions locales et pérennes, telles que la confection artisanale de serviettes hygiéniques réutilisables ; b. Garantir un accès universel à une information claire, honnête et adaptée à tous les membres de la communauté ; c. Mobiliser l'ensemble des acteurs (femmes, filles, hommes, leaders d'opinion, enseignants et soignants) pour un changement collectif ; d. Prioriser les besoins spécifiques des groupes les plus vulnérables, notamment les adolescentes, les femmes rurales et les personnes en situation de handicap\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1 ; d), (2 ; c), (3 ; a), (4 ; b)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(1 ; c), (2 ; a), (3 ; b), (4 ; d)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1 ; a), (2 ; d), (3 ; b), (4 ; c)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(1 ; b), (2 ; a), (3 ; c), (4 ; d)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. (1 ; c), (2 ; a), (3 ; b), (4 ; d)\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Inclusion = mobiliser tous les acteurs (c) ; Durabilité = solutions locales et pérennes (a) ; Transparence = information claire et honnête pour tous (b) ; Équité = priorité aux groupes vulnérables (d). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ali et Akama sont un couple qui applique la méthode du calendrier ; sachant que le cycle le plus court de Akissi compte 25 jours ; à partir de quel jour du cycle de Akissi, Louis doit-il se protéger en cas de rapport sexuel afin d'éviter que sa compagne soit enceinte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A partir du 5ème jour du cycle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"A partir du 6ème jour du cycle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"A partir du 7ème jour du cycle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"A partir du 8ème jour du cycle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. A partir du 7ème jour du cycle\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Méthode du calendrier : le premier jour fertile = cycle le plus court − 18. Ici 25 − 18 = 7 : protection à partir du 7e jour du cycle (exemple identique dans le cours). Remarque : Les prénoms du couple changent dans l'énoncé (Ali/Akama puis Akissi/Louis).\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 8 MAO, « Méthode du calendrier » (exemple 25 − 18 = 7)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__55\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°3 — Dans un lycée d'Abidjan, les garçons sont encouragés à suivre des filières scientifiques tandis que les filles sont orientées vers les filières littéraires et sociales. Aïcha L., brillante élève en mathématiques, souhaite intégrer la série scientifique, mais certains enseignants affirment que « les sciences sont faites pour les garçons ». Elle commence à perdre confiance en elle.\",\n       \"text\": \"Identifiez deux stéréotypes présents dans cette situation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les sciences sont réservées aux garçons.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les sciences sont réservées aux filles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les filles sont patientes et douces\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les filles réussissent mieux dans les matières littéraires.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les hommes sont autoritaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les sciences sont réservées aux garçons. ; D. Les filles réussissent mieux dans les matières littéraires.\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Les deux stéréotypes de la situation sont « les sciences sont réservées aux garçons » et, en miroir, « les filles réussissent mieux dans les matières littéraires » (orientation des filles vers les filières littéraires). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__56\",\n       \"num\": \"57\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les outils ou paramètres d'analyse du genre sont : (choisir 3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les rôles de genre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le pouvoir décisionnel\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le rôle de production\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le rôle communautaire\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'accès et le contrôle des ressources\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Les attentes et l'évaluation sociale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les rôles de genre ; B. Le pouvoir décisionnel ; E. L'accès et le contrôle des ressources\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient comme outils d'analyse du genre : les rôles de genre, le pouvoir décisionnel, l'accès et le contrôle des ressources. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__57\",\n       \"num\": \"58\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Comment la glaire cervicale se présente-t-elle à l'approche de l'ovulation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Abondante, fine, gluante, filante et translucide.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Modérée, épaisse, trouble (jaune).\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Augmentée, un peu épaisse, glissante, opaque, peu abondante et non filante.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Minimale, épaisse (collante), trouble.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Augmentée, un peu épaisse, glissante, opaque, peu abondante et non filante.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"À l'approche de l'ovulation, la glaire est augmentée, un peu épaisse, glissante, opaque, peu abondante et non filante. À l'ovulation elle devient abondante, fine, filante et translucide (blanc d'œuf).\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 8 MAO, « Méthode de Billings » et tableau de la glaire\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__58\",\n       \"num\": \"59\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour utiliser la Méthode des Jours Fixes, les femmes doivent avoir des cycles de quelle durée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Inférieurs à 26 jours.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De 26 à 32 jours.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Supérieurs à 32 jours.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"N'importe quelle durée de cycle.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. De 26 à 32 jours.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Critère d'éligibilité de la MJF : cycles de 26 à 32 jours ; la méthode ne peut pas être utilisée si le cycle est inférieur à 26 jours ou supérieur à 32 jours.\\n\\nSource : Cours SR/PF L2 INFAS (Document SSR L2 SF 2024-2025), chap. 8 MAO, « Méthode des jours fixes »\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j5-sfm__59\",\n       \"num\": \"60\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel est un bon principe de stockage pour les produits de santé ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Premier sorti, dernier entré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dernier entré, premier sorti\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Premier entré, premier sorti (PEPS / FIFO)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Empiler les produits pour gagner de la place\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Premier entré, premier sorti (PEPS / FIFO)\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le principe « Premier entré, premier sorti » (PEPS/FIFO) consiste à distribuer d'abord les produits reçus en premier, pour éviter la péremption. Le cours le cite parmi les affirmations du prétest de gestion logistique. (explication partiellement hors cours du projet)\\n\\nSource : Cours SR/PF 2023 L2 INFAS, Annexe 2 « Questionnaire prétest gestion logistique », item 22\",\n       \"sourceDoc\": \"Prépa D.E — J5 SSR/PF SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SR-PF_SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
